import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import net from "node:net";
const R = process.env.REV!;
const home = fs.mkdtempSync(path.join(os.tmpdir(), "p816home-"));
process.env.HOME = home;
fs.writeFileSync(path.join(home, "sentinel"), "x");
delete process.env.NEXUS_SANDBOX_NETWORK;
const { buildConfigWithPolicy } = await import(`${R}/cli/src/config.ts`);
const { ApplicationCore } = await import(`${R}/cli/src/core/app.ts`);
const { InteractiveRepl } = await import(`${R}/cli/src/repl.ts`);
const { SidecarServer } = await import(`${R}/cli/src/sidecar.ts`);
const { runDoctor } = await import(`${R}/cli/src/doctor.ts`);
const { mergePolicies } = await import(`${R}/cli/src/core/managed_policy.ts`);
const { policyWorld, toml } = await import(`${R}/cli/test/helpers/policy_enforcement.ts`);
const sandboxMod = await import(`${R}/cli/src/sandbox.ts`);
const forbidNet = policyWorld({ system: toml("[sandbox]", "forbid_network = true") }).host.managed().effective;
const required = policyWorld({ system: toml("[sandbox]", "required = true") }).host.managed().effective;
const none = mergePolicies();
const server = net.createServer((s) => s.end("hi")).listen(0, "127.0.0.1");
await new Promise((r) => server.once("listening", r));
const port = (server.address() as net.AddressInfo).port;
const only = process.env.ONLY;
const S: Array<[string, any, EffectivePolicy?, Record<string,string>?]> = [
  ["none", {}],
  ["bwrap", { sandbox: "bwrap" }],
  ["docker", { sandbox: "docker" }],
  ["bare --sandbox", { sandbox: true }],
  [":workspace", { sandbox: ":workspace" }],
  ["bwrap:workspace", { sandbox: "bwrap:workspace" }],
  [":read-only", { sandbox: ":read-only" }],
  ["bwrap:read-only", { sandbox: "bwrap:read-only" }],
  [":network", { sandbox: ":network" }],
  ["bwrap:network", { sandbox: "bwrap:network" }],
  ["docker:network", { sandbox: "docker:network" }],
  ["--sandbox bwrap --sandbox-network", { sandbox: "bwrap", sandboxNetwork: true }],
  ["--sandbox-network only (no sandbox)", { sandboxNetwork: true }],
  ["env NET=1 + bwrap", { sandbox: "bwrap" }, none, { NEXUS_SANDBOX_NETWORK: "1" }],
  ["env NET=1 + :workspace", { sandbox: ":workspace" }, none, { NEXUS_SANDBOX_NETWORK: "1" }],
  ["env NET=1 + :read-only", { sandbox: ":read-only" }, none, { NEXUS_SANDBOX_NETWORK: "1" }],
  ["--read-only", { readOnly: true }],
  ["--read-only --sandbox bwrap", { readOnly: true, sandbox: "bwrap" }],
  ["--read-only --sandbox bwrap --sandbox-network", { readOnly: true, sandbox: "bwrap", sandboxNetwork: true }],
  ["--mode read-only", { mode: "read-only" }],
  ["--mode read-only --sandbox bwrap", { mode: "read-only", sandbox: "bwrap" }],
  ["--read-only --sandbox :workspace", { readOnly: true, sandbox: ":workspace" }],
  ["env APPROVAL=read-only", {}, none, { NEXUS_APPROVAL_MODE: "read-only" }],
  ["policy forbid_net + :network", { sandbox: ":network" }, forbidNet],
  ["policy forbid_net + bwrap --sandbox-network", { sandbox: "bwrap", sandboxNetwork: true }, forbidNet],
  ["policy forbid_net + env NET=1 + bwrap", { sandbox: "bwrap" }, forbidNet, { NEXUS_SANDBOX_NETWORK: "1" }],
  ["policy forbid_net + :workspace", { sandbox: ":workspace" }, forbidNet],
  ["policy required + none", {}, required],
  ["policy required + --sandbox none", { sandbox: "none" }, required],
  ["policy required + :workspace", { sandbox: ":workspace" }, required],
];
for (const [name, opts, pol, env] of S) {
  if (only && !name.includes(only)) continue;
  const ws = fs.mkdtempSync(path.join(os.tmpdir(), "p816ws-"));
  fs.mkdirSync(path.join(ws, ".git"));
  for (const k of ["NEXUS_SANDBOX_NETWORK", "NEXUS_APPROVAL_MODE"]) delete process.env[k];
  Object.assign(process.env, env ?? {});
  const row: any = { name };
  let config: any;
  try {
    config = buildConfigWithPolicy({ endpoint: "http://127.0.0.1:1/v1", model: "m", workspace: ws, ...opts }, pol ?? none);
  } catch (e: any) { row.refused = String(e.message).slice(0, 110); console.log(JSON.stringify(row)); continue; }
  config.coreBinaryPath = `${R}/core/target/release/harness-core`;
  row.cfg = { sandbox: config.sandbox, profile: config.sandboxProfile, ro: config.readOnly, mode: config.approvalMode, net: sandboxMod.sandboxNetworkEnabled() };
  const app = new ApplicationCore(config);
  const events: any[] = [];
  const sc = new SidecarServer({ app, mode: config.approvalMode ?? "review", write: (l: string) => events.push(JSON.parse(l)), historyFile: path.join(home, "h") });
  (sc as any).emitSessionState();
  const st = events.filter((e) => e.type === "session.state").at(-1);
  row.sidecar = `${st.posture.sandbox} | ${st.posture.profile}`;
  const repl = new InteractiveRepl(app, config.approvalMode ?? "review");
  const logs: string[] = []; const rl = console.log; console.log = (...a: unknown[]) => void logs.push(a.join(" "));
  try { (repl as any).printStatus(false); } finally { console.log = rl; }
  const line = logs.join("\n").replace(/\u001b\[[0-9;]*m/g, "").split("\n").find((l) => l.startsWith("mode: ")) ?? "";
  row.repl = /sandbox: (.*) · workspace:/.exec(line)?.[1];
  const rep = await runDoctor({ config, home, timeoutMs: 800 });
  row.doctor = `${rep.posture?.sandbox} | ${rep.posture?.profile} | ${rep.posture?.profileSource}`;
  const f = rep.findings.find((x: any) => x.id === "sandbox.confinement");
  row.doctorFinding = f ? `${f.status}: ${String(f.explanation).slice(0, 160)}` : "none";
  // enforcement
  const agent: any = app.getAgent();
  const bridge: any = agent.bridge;
  const cmd = `echo NET=$(timeout 3 bash -c 'exec 3<>/dev/tcp/127.0.0.1/${port}' 2>/dev/null && echo yes || echo no); echo HOME=$([ -e ${home}/sentinel ] && echo visible || echo hidden); (touch ${ws}/probe_w 2>/dev/null && echo WS=writable || echo WS=ro); (touch /dev/shm/p816out_$$ 2>/dev/null && echo OUT=writable && rm -f /dev/shm/p816out_$$ || echo OUT=ro)`;
  let res: any;
  try { res = await bridge.executeTool("run_command", { command: cmd, timeout_secs: 20 }); } catch (e: any) { res = { error: String(e) }; }
  row.cmd = res.success ? String(res.output).trim().split("\n").join(" ") : `FAIL ${String(res.error ?? res.output).slice(0, 140)}`;
  try { row.workerEngine = bridge.workerEngine(); } catch (e) { row.workerEngine = "err"; }
  row.toolReadOnly = bridge.readOnly;
  app.shutdown();
  console.log(JSON.stringify(row));
}
server.close(); process.exit(0);
EOF
