import fs from "node:fs"; import path from "node:path"; import os from "node:os"; import { spawnSync } from "node:child_process";
const R = process.env.REV!;
const home = fs.mkdtempSync(path.join(os.tmpdir(), "p816h-")); process.env.HOME = home; fs.writeFileSync(path.join(home, "sentinel"), "x");
const ws = fs.mkdtempSync(path.join(os.tmpdir(), "p816w-"));
const sb: any = await import(`${R}/cli/src/sandbox.ts`);
const { setSandboxNetworkFlag } = sb;
const core = `${R}/core/target/release/harness-core`;
for (const net of [false, true]) {
  setSandboxNetworkFlag(net);
  for (const e of ["bwrap", "docker"] as const) {
    const w = sb.wrapSandboxedWorker(core, ["--workspace", ws, "rpc"], ws, { engines: [e] });
    console.log(`WORKER flag=${net} engine=${e} sandboxed=${w.sandboxed} netIsolated=${(w.args??[]).includes("--unshare-net") || (w.args??[]).includes("none") } net-arg=${(w.args??[]).filter((a:string)=>/net/.test(a)).join(",")}`);
    const f = sb.wrapSandboxedWorker(core, ["--workspace", ws, "--files-only", "rpc"], ws, { engines: [e], network: false });
    console.log(`  files-worker net-arg=${(f.args??[]).filter((a:string)=>/net/.test(a)).join(",")}`);
  }
}
setSandboxNetworkFlag(true);
// read-only command wrap with flag on
const fd = fs.openSync(ws, "r");
for (const mode of ["bwrap", "auto"]) {
  const r = sb.wrapSandboxedCommand(`ls ${home}/sentinel; cat /etc/hostname; touch ${ws}/x`, ws, { mode, shell: "bash", readOnlyHost: true, workspaceFd: fd, network: false });
  console.log(`RO mode=${mode} sandboxed=${r.sandboxed} engine=${r.engine} unshare-net=${(r.argv??[]).includes("--unshare-net")} warn=${r.warning ?? ""}`);
  if (r.argv) { const p = spawnSync(r.argv[0], r.argv.slice(1), { encoding: "utf8", stdio: ["ignore","pipe","pipe"], cwd: ws }); console.log("  out:", JSON.stringify(p.stdout.slice(0,120)), "err:", JSON.stringify(p.stderr.slice(0,200))); }
}
// docker write-mode args
for (const net of [false,true]) { setSandboxNetworkFlag(net); const d = sb.wrapSandboxedCommand("true", ws, { mode: "docker", shell: "bash" }); console.log(`DOCKER cmd flag=${net} sandboxed=${d.sandboxed} net-args=${(d.argv??[]).filter((a:string)=>/net|none/.test(a)).join(",")} warn=${d.warning??""}`); }
process.exit(0);
EOF
