cd /tmp/claude-1000/-home-mike-nexus-code/43bcbb67-2cff-4fa8-a05e-f8aa598df73b/scratchpad/p816 && cat > den.mts <<'EOF'
import fs from "node:fs"; import path from "node:path"; import os from "node:os";
const R = process.env.REV!;
const home = fs.mkdtempSync(path.join(os.tmpdir(), "p816dh-")); process.env.HOME = home;
const { buildConfigWithPolicy } = await import(`${R}/cli/src/config.ts`);
const { ApplicationCore } = await import(`${R}/cli/src/core/app.ts`);
const { mergePolicies } = await import(`${R}/cli/src/core/managed_policy.ts`);
const cases: Array<[string, any]> = [["none(sandbox bwrap)", { sandbox: "bwrap" }], ["bare --sandbox", { sandbox: true }], [":workspace", { sandbox: ":workspace" }], ["bwrap:network", { sandbox: "bwrap:network" }], [":read-only", { sandbox: ":read-only" }], ["--read-only", { readOnly: true }]];
for (const [name, o] of cases) {
  const ws = fs.mkdtempSync(path.join(os.tmpdir(), "p816dw-")); fs.mkdirSync(path.join(ws, ".git"));
  const config = buildConfigWithPolicy({ endpoint: "http://127.0.0.1:1/v1", model: "m", workspace: ws, ...o }, mergePolicies());
  config.coreBinaryPath = `${R}/core/target/release/harness-core`;
  const app = new ApplicationCore(config); const agent: any = app.getAgent();
  const oldPath = process.env.PATH; process.env.PATH = "/nonexistent";
  try {
    await agent.dispatchToolCall({ id: "c1", type: "function", function: { name: "run_command", arguments: JSON.stringify({ command: "ls" }) } }, 1, "agent", async () => true);
  } catch (e: any) { console.log("  threw", String(e).slice(0,100)); }
  process.env.PATH = oldPath;
  console.log(name, JSON.stringify(agent.getSandboxDenialEvents().map((e: any) => ({ kind: e.kind, engine: e.engine, profile: e.profile, op: e.operation, cat: e.category, reason: e.reason.slice(0, 90) }))));
  app.shutdown();
}
process.exit(0);
EOF
